select p.team_id, count(*) n, sum(proj_toi_es_seconds) es, sum(proj_toi_pp_seconds) pp, sum(proj_toi_pk_seconds) pk, round(avg(proj_toi_es_seconds+proj_toi_pp_seconds+proj_toi_pk_seconds)/60.0,2) avg_toi_min, round(max(proj_toi_es_seconds+proj_toi_pp_seconds+proj_toi_pk_seconds)/60.0,2) max_toi_min, round(sum(proj_shots_es+proj_shots_pp+coalesce(proj_shots_pk,0)),2) shots, round(sum(proj_goals_es+proj_goals_pp+coalesce(proj_goals_pk,0)),2) goals, round(sum(proj_assists_es+proj_assists_pp+coalesce(proj_assists_pk,0)),2) assists, (select round(t.proj_shots_es+t.proj_shots_pp,2) from forge_team_projections t where t.run_id=p.run_id and t.team_id=p.team_id) team_shots, (select round(t.proj_goals_es+t.proj_goals_pp,2) from forge_team_projections t where t.run_id=p.run_id and t.team_id=p.team_id) team_goals, (select t.proj_toi_es_seconds from forge_team_projections t where t.run_id=p.run_id and t.team_id=p.team_id) team_es from forge_player_projections p where p.run_id='26373189-3ebd-4380-b4f4-c6797d469ca9' group by p.run_id, p.team_id
